<?php declare(strict_types=1); namespace App\Controller; use Cake\Http\Response; class ResidentesController extends AppController { public function search():Response {$term=trim((string)$this->request->getQuery('q',''));if(mb_strlen($term)<2)return $this->response->withType('application/json')->withStringBody('[]');$like='%'.$term.'%';$items=$this->Residentes->find()->distinct(['Residentes.id'])->where(['OR'=>['document_number LIKE'=>$like,'full_name LIKE'=>$like]])->limit(10)->all();$results=[];foreach($items as $item){$results[]=['id'=>$item->id,'label'=>$item->document_number.' — '.$item->full_name];}return $this->response->withType('application/json')->withStringBody(json_encode($results));} public function index():?Response {$this->set('residentes',$this->Residentes->find()->contain(['Viviendas'])->orderBy(['Residentes.active'=>'DESC','Residentes.full_name'=>'ASC'])->all());return null;} public function add():?Response {$residente=$this->Residentes->newEmptyEntity();if($this->request->is('post')){$residente=$this->Residentes->patchEntity($residente,$this->request->getData());if($this->Residentes->save($residente)){$this->Flash->success(__('Residente registrado correctamente.'));return $this->redirect(['action'=>'index']);}}$this->set(compact('residente'));$this->lists();return null;} public function edit(int $id):?Response {$residente=$this->Residentes->get($id);if($this->request->is(['post','put','patch'])){$residente=$this->Residentes->patchEntity($residente,$this->request->getData());if($this->Residentes->save($residente)){$this->Flash->success(__('Residente actualizado correctamente.'));return $this->redirect(['action'=>'index']);}}$this->set(compact('residente'));$this->lists();return null;} private function lists():void {$this->set('viviendas',$this->fetchTable('Viviendas')->find('list')->all());} }
